package com.example.lokinavflowui;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.*;import android.content.res.loader.*;import java.io.*;import dalvik.system.PathClassLoader;
public final class UiAudit extends Instrumentation {String run,filter;public void onCreate(Bundle b){super.onCreate(b);run=b.getString("run","");filter=b.getString("filter","");start();}public void onStart(){Bundle result=new Bundle();Activity host=null;try{if(!run.matches("[a-f0-9]{12}"))throw new Exception("Invalid run");Context base=getTargetContext();File root=new File(base.getFilesDir(),"run-"+run);PathClassLoader loader=new PathClassLoader(new File(root,"checks.dex").getPath()+":"+new File(root,"glass.apk").getPath()+":"+new File(root,"phone.apk").getPath(),ClassLoader.getSystemClassLoader());Resources resources=new Resources(base.getAssets(),base.getResources().getDisplayMetrics(),base.getResources().getConfiguration());ResourcesLoader assets=new ResourcesLoader();try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(new File(root,"phone.apk"),ParcelFileDescriptor.MODE_READ_ONLY)){assets.addProvider(ResourcesProvider.loadFromApk(fd));}resources.addLoaders(assets);Context wrapper=new ContextWrapper(base){public Context getApplicationContext(){return this;}public ClassLoader getClassLoader(){return loader;}public Resources getResources(){return resources;}public AssetManager getAssets(){return resources.getAssets();}};host=startActivitySync(new Intent(base,UiHost.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Class<?> checks=loader.loadClass("com.example.rokidkeyboardbridge.NavigationFlowUiChecks");checks.getField("only").set(null,filter);Object data=checks.getMethod("run",Context.class,Activity.class).invoke(null,wrapper,host);try(FileOutputStream out=new FileOutputStream(new File(root,"result.json"))){out.write(data.toString().getBytes("UTF-8"));}result.putString("result","PASS interaction checks completed");finish(Activity.RESULT_OK,result);}catch(Throwable e){while(e.getCause()!=null)e=e.getCause();result.putString("failure",e.getClass().getSimpleName()+":"+e.getMessage());finish(Activity.RESULT_CANCELED,result);}finally{if(host!=null){Activity finalHost=UiHost.current!=null?UiHost.current:host;runOnMainSync(finalHost::finish);}}}}
